def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def candies(M, N):
    if gcd(M, N) != 1:
        return 0  # If M and N are not coprime, Pacman can visit all positions.

    max_position = M * N - M - N + 1  # Maximum position reachable using M and N.
    reachable = [False] * (max_position + 1)
    reachable[0] = True

    for i in range(max_position + 1):
        if reachable[i]:
            if i + M <= max_position:
                reachable[i + M] = True
            if i + N <= max_position:
                reachable[i + N] = True

    return sum(1 for i in range(1, max_position + 1) if not reachable[i])

# Example usage:
# print(candies(2, 5))  # Output: 2
# print(candies(2, 7))  # Output: 3
# print(candies(25, 7)) # Output: 72
